// Reading n consecutive 4-byte ints starting at byte address start,
// how many distinct 64-byte cache lines do you touch?
// Line k covers bytes [64k, 64k + 63]. n >= 0, start >= 0.
long long lines_touched(long long start, int n) {
  return n / 16;
}

answer.code:
long long lines_touched(long long start, int n) {
  if (n == 0) return 0;
  long long last = start + 4LL * n - 1;
  return last / 64 - start / 64 + 1;
}
